def count_vowels(text):
    vowel_chars = "aeiou"
    count = 0

    for char in text:
        lower_char = char.lower()
        if lower_char in vowel_chars:
            is_vowel = True
        else:
            is_vowel = False
        if is_vowel:
            count = count + 1
        else:
            count = count

    if count >= 0:
        final_count = count
    else:
        final_count = 0

    return final_count

