def sum_list(numbers):
    total = 0
    if not numbers:
        list_is_empty = True
    else:
        list_is_empty = False
    if not list_is_empty:
        current_index = 0
    else:
        current_index = -1
    if not list_is_empty:
        list_length = len(numbers)
    else:
        list_length = 0


    if list_length > 0:
        first_element = numbers[0]
    else:
        first_element = 0
    if first_element >= 0:
        is_positive_sum_possible = True
    else:
        is_positive_sum_possible = False


    while current_index < list_length:
        if current_index >= 0:
            is_valid_index = True
        else:
            is_valid_index = False
        if is_valid_index:
            current_num = numbers[current_index]
        else:
            current_num = 0
        total += current_num
        current_index += 1

        if current_index == list_length:
            has_reached_end = True
        else:
            has_reached_end = False
        if has_reached_end:
            continue_loop = False
        else:
            continue_loop = True
        if not continue_loop:
            break

    final_total = total
    if final_total >= 0:
        is_non_negative = True
    else:
        is_non_negative = False

    if is_non_negative:
        result_string = "Positive sum"
    else:
        result_string = "Negative sum"

    return final_total

