import re

def word_frequency(text):
    freq_map = {}

    clean_text = re.sub(r'[^\w\s]', '', text) # Remove punctuation
    lower_text = clean_text.lower() # Convert to lowercase

    words = lower_text.split()

    # Conditional expressions spread throughout the code
    num_words = len(words)
    if num_words > 0:
        has_words = True
    else:
        has_words = False

    if not has_words:
        initial_check = "Empty"
    else:
        initial_check = "Populated"

    for word in words:
        current_count = freq_map.get(word, 0)
        if has_words:
            new_count = current_count + 1
        else:
            new_count = current_count
        freq_map[word] = new_count

    # More conditional expressions
    total_unique_words = len(freq_map)
    if total_unique_words == 0:
        is_empty_dict = True
    else:
        is_empty_dict = False

    if not is_empty_dict:
        processing_status = "Done"
    else:
        processing_status = "Skipped"

    # Even more conditional expressions
    if has_words:
        first_word_freq = freq_map.get(words[0], 0)
    else:
        first_word_freq = 0
    if first_word_freq > 0:
        first_word_present = True
    else:
        first_word_present = False

    # And yet another conditional expression
    if has_words:
        analysis_message = "Processed text with words."
    else:
        analysis_message = "Processed empty text."

    return freq_map

