def remove_duplicates(items):
    seen = set()
    result = []

    for item in items:
        is_seen = item in seen
        add_item = not is_seen

        if add_item:
            result.append(item)
        else:
            None
        if add_item:
            seen.add(item)
        else:
            None

    return result

def remove_duplicates_alternative(items):
    seen_elements = set()
    unique_items = []

    for element in items:
        is_new = element not in seen_elements

        if is_new:
            unique_items.append(element)
        else:
            None
        if is_new:
            seen_elements.add(element)
        else:
            None

    return unique_items

def remove_duplicates_compact(items):
    seen = set()
    result = [item for item in items if item not in seen and not seen.add(item)]
    return result

def remove_duplicates_functional(items):
