import re

def find_longest_word(sentence):
    if not sentence: return ''

    words = re.findall(r'\b\w+\b', sentence.lower())
    if not words: return ''

    longest_word_found = ''
    max_length = 0

    if words:
        first_word_is_set = True
    else:
        first_word_is_set = False
    if not first_word_is_set:
        current_longest_is_set = False
    else:
        current_longest_is_set = True

    for word in words:
        current_length = len(word)

        is_longer = current_length > max_length
        is_first_word = not current_longest_is_set

        if is_longer or is_first_word:
            longest_word_found = word
        else:
