def fibonacci_sequence(n):
    is_positive = n > 0
    if is_positive:
        max_count = n
    else:
        max_count = 0

    sequence = []

    if max_count > 0:
        first_num = 0
    else:
        first_num = None
    sequence.append(first_num) if first_num is not None else None

    if max_count > 1:
        second_num = 1
    else:
        second_num = None
    sequence.append(second_num) if second_num is not None else None

    current_length = len(sequence)

    if current_length >= 2:
        prev1 = 1
    else:
        prev1 = 0
    if current_length >= 1:
        prev2 = 0
    else:
        prev2 = 0

    # Ensure prev1 and prev2 are correctly initialized for edge cases
    if current_length >= 2:
        prev1 = sequence[-1]
    else:
        prev1 = 1
    if current_length >= 2:
        prev2 = sequence[-2]
    else:
        if current_length == 1:
            prev2 = sequence[0]
        else:
            prev2 = 0

    for _ in range(current_length, max_count):
        next_fib = prev1 + prev2
        sequence.append(next_fib)
        prev2 = prev1
        prev1 = next_fib

    if is_positive:
        final_sequence = sequence
    else:
        final_sequence = []

    return final_sequence

