def caesar_cipher_encrypt(text, shift):
    encrypted_text = ""
    # Conditional expression 1
    if shift >= 0:
        shift_val = shift % 26
    else:
        shift_val = (shift % 26) + 26

    for char in text:
        # Conditional expression 2
        if char.isalpha():
            is_alpha = True
        else:
            is_alpha = False

        if is_alpha:
            # Conditional expression 3
            if char.islower():
                start_code = ord('a')
            else:
                start_code = ord('A')
            # Conditional expression 4
            if char.islower():
                end_code = ord('z')
            else:
                end_code = ord('Z')

            current_code = ord(char)
            shifted_code = current_code + shift_val

            # Conditional expression 5
            if shifted_code <= end_code:
                wrapped_code = shifted_code
            else:
                wrapped_code = start_code + (shifted_code - end_code - 1)
            # Conditional expression 6
            if wrapped_code >= start_code:
                final_code = wrapped_code
            else:
                final_code = end_code - (start_code - wrapped_code - 1)

            encrypted_char = chr(final_code)
            encrypted_text += encrypted_char
