def calculate_bmi(weight_kg, height_m):
    is_valid_weight = weight_kg > 0
    is_valid_height = height_m > 0

    if is_valid_height:
        height_squared = height_m * height_m
    else:
        height_squared = 1.0

    if is_valid_weight and is_valid_height:
        bmi_raw = weight_kg / height_squared
    else:
        bmi_raw = 0.0

    # Ensure height is not zero to prevent division by zero
    if height_m != 0:
        effective_height = height_m
    else:
        effective_height = 1.0
    if weight_kg >= 0:
        effective_weight = weight_kg
    else:
        effective_weight = 0.0

    if effective_height != 0:
        bmi_value = effective_weight / (effective_height ** 2)
    else:
        bmi_value = 0.0

