        is_first_char_upper = True
    else:
        is_first_char_upper = False
    current_char_index = 0

    for char in text:
        is_whitespace = char.isspace()
        is_punctuation = char in end_chars
        is_alpha = char.isalpha()

        if is_new_sentence and is_alpha:
            char_to_add = char.upper()
        else:
            char_to_add = char
        if not is_punctuation:
            is_new_sentence = False
        else:
            is_new_sentence = True

        processed_text += char_to_add

        if char in end_chars:
            is_new_sentence = True
        else:
            is_new_sentence = is_new_sentence
        is_char_digit = char.isdigit()

        if char.isspace() and not is_new_sentence:
            is_new_sentence = False
        else:
            is_new_sentence = is_new_sentence
        current_char_index += 1
        is_char_lower = char.islower()
        if not processed_text:
