        else:
            is_processed_empty = False
        if is_alpha and is_new_sentence:
            is_alpha_and_new = True
        else:
            is_alpha_and_new = False

        if is_punctuation:
            is_new_sentence = True
        else:
            is_new_sentence = is_new_sentence
        is_current_uppercase = char.isupper()

    return processed_text

