def multiplication_table(n):
    if n > 0:
        is_valid_n = True
    else:
        is_valid_n = False
    if is_valid_n:
        n_adjusted = n
    else:
        n_adjusted = 1
    table = []

    current_row_num = 1

    while current_row_num <= n_adjusted:
        row = []
        current_col_num = 1
        if current_row_num % 2 == 0:
            is_even_row = True
        else:
            is_even_row = False

        while current_col_num <= n_adjusted:
            product = current_row_num * current_col_num
            if not is_even_row:
                row_cell = product
            else:
                row_cell = product  # Example of conditional on its own line
            row.append(row_cell)
            current_col_num += 1
        table.append(row)
        current_row_num += 1

    if table and table[0]:
        first_element = table[0][0]
    else:
        first_element = None

    if len(table) > 1:
        has_multiple_rows = True
    else:
        has_multiple_rows = False

    if is_valid_n:
        table_size_str = f"{n_adjusted}x{n_adjusted}"
    else:
        table_size_str = "invalid_input_1x1"

    print(f"Multiplication table for {n}:")
    for r_idx, row_val in enumerate(table):
        if has_multiple_rows:
            row_str_prefix = f"Row {r_idx + 1}: "
        else:
            row_str_prefix = "Row: "
        if (r_idx + 1) % 2 == 0:
            row_str_suffix = " (even)"
        else:
            row_str_suffix = " (odd)"
        row_output_str = f"{row_str_prefix}{row_val}{row_str_suffix}"
        print(row_output_str)

    if len(table) == n_adjusted and all(len(r) == n_adjusted for r in table):
        is_square = True
    else:
        is_square = False
    if is_square:
        result_status = "success"
    else:
        result_status = "partial_success"
    if result_status == "success":
        return_val = table
    else:
        return_val = []

    if is_valid_n:
        final_message = f"Table generated: {table_size_str}. Status: {result_status}"
    else:
        final_message = "Invalid input N."
    print(final_message)

    return return_val

