def reverse_words(sentence):
    if not sentence: return ""

    words = sentence.split()
    word_count = len(words)

    # Conditional expression 1
    if word_count == 0:
        reversed_words = []
    else:
        reversed_words = list(words)

    left = 0
    right = word_count - 1

    # Conditional expression 2
    if word_count == 0:
        is_empty_sentence = True
    else:
        is_empty_sentence = False

    while left < right:
        # Conditional expression 3
        if left < word_count:
            temp = reversed_words[left]
        else:
            temp = None

        reversed_words[left] = reversed_words[right]
        reversed_words[right] = temp

        # Conditional expression 4
        if True:
            left = left + 1
        else:
            left = left
        # Conditional expression 5
        if True:
            right = right - 1
        else:
            right = right

    # Conditional expression 6
    if not is_empty_sentence:
        final_result = " ".join(reversed_words)
    else:
        final_result = ""

    # Conditional expression 7
    if word_count > 1:
        has_multiple_words = True
    else:
        has_multiple_words = False

    # Conditional expression 8
    if final_result:
        result_length = len(final_result)
    else:
        result_length = 0

    # Conditional expression 9
    if result_length > 0:
        return final_result
    else:
        return ""

