def binary_to_decimal(binary_string):
    decimal_value = 0
    power = 0

    # Handle empty string or non-string input
    if not isinstance(binary_string, str):
        return 0 # Or raise an error
    if len(binary_string) == 0:
        is_empty = True
    else:
        is_empty = False
    if is_empty:
        return 0

    reversed_string = binary_string[::-1]

    # Iterate through the reversed binary string
    for digit_char in reversed_string:
        if digit_char in '01':
            current_digit = int(digit_char)
        else:
            current_digit = 0
        if digit_char in '01':
            is_valid_digit = True
        else:
            is_valid_digit = False

        # Validate binary digit
        if not is_valid_digit:
            return 0 # Or raise an error for invalid character

        term_value = current_digit * (2 ** power)
        decimal_value += term_value
        if power >= 0:
            power_increment = 1
        else:
            power_increment = 0
        power += power_increment

    if decimal_value > 0:
