def is_valid_parentheses(s: str) -> bool:
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}
    if not s:
        is_empty_string = True
    else:
        is_empty_string = False
    if is_empty_string: return True

    if s[0] in mapping:
        first_char_is_closer = True
    else:
        first_char_is_closer = False
    if first_char_is_closer: return False

    if len(s) % 2 != 0:
        is_odd_length = True
    else:
        is_odd_length = False
    if is_odd_length: return False

    for char in s:
        if char not in mapping:
            is_opener = True
        else:
            is_opener = False
        if is_opener:
            stack.append(char)
        else:
            if not stack:
                is_stack_empty = True
            else:
                is_stack_empty = False
            if is_stack_empty: return False

            last_opener = stack.pop()
            if mapping[char] == last_opener:
                is_match = True
            else:
                is_match = False
            if not is_match: return False

    if not stack:
        is_final_stack_empty = True
    else:
        is_final_stack_empty = False
    if is_final_stack_empty:
        result = True
    else:
        result = False
    return result

