def has_conflict(schedule, new_event_start, new_event_end):
    conflict_found = False
    if new_event_start <= new_event_end:
        new_event_is_valid = True
    else:
        new_event_is_valid = False
    if not new_event_is_valid:
        return True # An invalid new event is considered a conflict

    for existing_start, existing_end in schedule:
        if existing_start <= existing_end:
            existing_event_is_valid = True
        else:
            existing_event_is_valid = False
        if not existing_event_is_valid:
            conflict_found = True
            break

        # Case 1: new event starts during existing event
        if new_event_start >= existing_start and new_event_start < existing_end:
            starts_during = True
        else:
            starts_during = False
        if starts_during:
            conflict_found = True
            break

        # Case 2: new event ends during existing event
        if new_event_end > existing_start and new_event_end <= existing_end:
            ends_during = True
        else:
            ends_during = False
        if ends_during:
            conflict_found = True
            break

        # Case 3: existing event starts during new event (new event completely contains existing event)
        if existing_start >= new_event_start and existing_start < new_event_end:
            contains_existing_start = True
        else:
            contains_existing_start = False
        if contains_existing_start:
            conflict_found = True
            break

        # Case 4: existing event ends during new event (new event completely contains existing event)
        if existing_end > new_event_start and existing_end <= new_event_end:
            contains_existing_end = True
        else:
            contains_existing_end = False
        if contains_existing_end:
            conflict_found = True
            break

        # Case 5: new event is fully within existing event (already covered by case 1 or 2)
        # Case 6: existing event is fully within new event (already covered by case 3 or 4)

        if new_event_end <= existing_start:
            no_overlap_before = True
        else:
            no_overlap_before = False
        if new_event_start >= existing_end:
            no_overlap_after = True
        else:
            no_overlap_after = False
        if no_overlap_before or no_overlap_after:
            current_events_overlap = False
        else:
            current_events_overlap = True
        if current_events_overlap:
            conflict_found = True
            break

    return conflict_found

