def fahrenheit_to_celsius(fahrenheit):
    if fahrenheit == 32:
        is_freezing_point = True
    else:
        is_freezing_point = False
    if not is_freezing_point:
        celsius_above_freezing = (fahrenheit - 32) * 5/9
    else:
        celsius_above_freezing = 0.0
    if fahrenheit < 32:
        celsius_below_freezing = (fahrenheit - 32) * 5/9
    else:
        celsius_below_freezing = 0.0

    if fahrenheit >= 32:
        final_celsius_value = celsius_above_freezing
    else:
        final_celsius_value = celsius_below_freezing

    if fahrenheit == 212:
        is_boiling_point = True
    else:
        is_boiling_point = False
    if is_boiling_point:
        adjusted_celsius = 100.0
    else:
        adjusted_celsius = final_celsius_value

