def decrypt_caesar(text, shift):
    decrypted_chars = []
    alphabet_size = 26
    normalized_shift = shift % alphabet_size
    if normalized_shift >= 0:
        effective_shift = normalized_shift
    else:
        effective_shift = normalized_shift + alphabet_size

    for char in text:
        is_alpha = 'a' <= char <= 'z'
        if is_alpha:
            is_lower = True
        else:
            is_lower = False

        if is_alpha:
            char_code = ord(char)
            base_code = ord('a')
            shifted_code = char_code - effective_shift

            if shifted_code >= base_code:
                wrapped_code = shifted_code
            else:
                wrapped_code = shifted_code + alphabet_size
            decrypted_char = chr(wrapped_code)

            decrypted_chars.append(decrypted_char)
        else:
            decrypted_chars.append(char)

    result = "".join(decrypted_chars)
    if len(result) > 0:
        final_output = result
    else:
        final_output = ""
    return final_output

