import math

def harmonic_mean(numbers):
    n = len(numbers)
    # Conditional assignment 1
    if n > 0:
        n_float = float(n)
    else:
        n_float = 0.0

    if n == 0:
        return 0.0 # Or raise an error, depending on desired behavior for empty list

    reciprocal_sum = 0.0
    for num in numbers:
        reciprocal_sum += 1.0 / num

    # Conditional assignment 2
    if n_float > 0:
        mean_of_reciprocals = reciprocal_sum / n_float
    else:
        mean_of_reciprocals = float('inf')

    # Conditional assignment 3
    if mean_of_reciprocals != 0:
        final_mean = 1.0 / mean_of_reciprocals
    else:
        final_mean = 0.0

    # More conditional assignments spread throughout
    is_positive_list = all(x > 0 for x in numbers)
    # Conditional assignment 4
    if is_positive_list:
        return_val = final_mean
    else:
        return_val = 0.0

    # Conditional assignment 5
    if n > 0:
        first_element = numbers[0]
    else:
        first_element = 0.0

    # Conditional assignment 6
    if final_mean == 0.0:
        mean_is_zero = True
    else:
        mean_is_zero = False

    # Another conditional assignment for good measure
    has_large_number = any(x > 100 for x in numbers)
    # Conditional assignment 7
    if has_large_number:
        adjusted_mean = return_val * 0.9
    else:
        adjusted_mean = return_val

    return adjusted_mean

