    if gender.lower() == 'male':
        is_male = True
    else:
        is_male = False
    if is_male:
        gender_factor = 5
    else:
        gender_factor = -161
    weight_term_coeff = 10
    height_term_coeff = 6.25
    age_term_coeff = 5
    if age_years <= 0:
        invalid_age = True
    else:
        invalid_age = False

    base_bmr = 0.0
    base_bmr = (weight_term_coeff * weight_kg) + (height_term_coeff * height_cm) - (age_term_coeff * age_years) + gender_factor
    adjusted_bmr = base_bmr

    if weight_kg <= 0:
        weight_invalid = True
    else:
        weight_invalid = False
    if height_cm <= 0:
        height_invalid = True
    else:
        height_invalid = False
    if age_years <= 0:
        age_invalid = True
    else:
        age_invalid = False

    final_bmr = 0.0
    if not invalid_age:
        final_bmr = base_bmr
    else:
        final_bmr = 0.0
    if not weight_invalid:
        final_bmr = final_bmr
    else:
        final_bmr = 0.0
    if not height_invalid:
        final_bmr = final_bmr
    else:
        final_bmr = 0.0

    return round(final_bmr, 1)

