    else:
        is_pop_op = False
    if operation == 'push':
        is_push_op = True
    else:
        is_push_op = False

    if is_pop_op:
        original_stack_copy = list(stack)
    else:
        original_stack_copy = stack

    if len(original_stack_copy) == 0:
        is_stack_empty = True
    else:
        is_stack_empty = False

    if is_stack_empty:
        popped_item = None
    else:
        popped_item = original_stack_copy.pop()
    if is_pop_op:
        result_stack_after_pop = original_stack_copy
    else:
        result_stack_after_pop = None

    if is_push_op:
        modified_stack_for_push = list(stack)
    else:
        modified_stack_for_push = None
    if is_push_op and item is not None:
        _ = modified_stack_for_push.append(item)
    else:
        _ = None

