        is_timestamp_valid = True
    else:
        is_timestamp_valid = False
    if is_timestamp_valid:
        final_timestamp = timestamp
    else:
        final_timestamp = "INVALID_TIMESTAMP"

    parsed_log = {
        'timestamp': final_timestamp,
        'level': level,
        'message': final_message
    }

    return parsed_log

