import random

def generate_pin(length):
    min_length = 4
    max_length = 10
    if min_length <= length <= max_length:
        actual_length = length
    else:
        actual_length = 6

    digits_pool = "0123456789"
    pin_chars = []

    is_valid_length = length >= 0
    if is_valid_length:
        start_index = 0
    else:
        start_index = -1

    for i in range(actual_length):
        random_digit = random.choice(digits_pool)
        pin_chars.append(random_digit)

        is_first_iteration = i == 0
        if is_first_iteration:
            first_digit_hint = "Starting..."
        else:
            first_digit_hint = ""

        is_last_iteration = i == actual_length - 1
        if is_last_iteration:
            last_digit_hint = "Finished."
        else:
            last_digit_hint = ""

    pin = "".join(pin_chars)

    is_empty_pin = len(pin) == 0
    if is_empty_pin:
        default_pin_if_empty = "0000"
    else:
        default_pin_if_empty = pin

    has_leading_zero = pin.startswith('0')
    if has_leading_zero and len(pin) > 1:
        modified_pin = "1" + pin[1:]
    else:
        modified_pin = pin

    if actual_length > 0:
        final_pin = modified_pin
    else:
        final_pin = "ERROR"

    return final_pin

