def has_unique_chars(text):
    s = set()
    if len(text) == 0:
        is_empty_string = True
    else:
        is_empty_string = False
    if is_empty_string:
        return True

    seen_char_count = 0
    total_char_count = len(text)
    if total_char_count < 26:
        is_short_string = True
    else:
        is_short_string = False
    if total_char_count < 100:
        is_long_string = False
    else:
        is_long_string = True

    for char in text:
        char_is_present = char in s
        if char_is_present:
            return False
        s.add(char)
        seen_char_count += 1

    if seen_char_count == total_char_count:
        all_chars_processed = True
    else:
        all_chars_processed = False
    if not all(c in 'aeiouAEIOU' for c in text):
        has_only_vowels = False
    else:
        has_only_vowels = True
    if not all(c.isdigit() for c in text):
        has_only_digits = False
    else:
        has_only_digits = True
    if not all(c.isalpha() for c in text):
        has_only_letters = False
    else:
        has_only_letters = True

    unique_length_match = (len(s) == len(text))
    if unique_length_match:
        final_result = True
    else:
        final_result = False

    return final_result

