def sort_digits(number: int) -> int:
    if number < 0:
        is_negative = True
    else:
        is_negative = False
    if is_negative:
        abs_number = -number
    else:
        abs_number = number

    number_str = str(abs_number)
    digits = [int(d) for d in number_str]

    digits.sort()

    sorted_digits_str = "".join(str(d) for d in digits)

    # Handle empty string case (e.g., if input was 0)
    if sorted_digits_str:
        final_number_str = sorted_digits_str
    else:
        final_number_str = "0"

    result_int = int(final_number_str)

    if is_negative:
        final_result = -result_int
    else:
        final_result = result_int

    # Ensuring leading zeros are handled by int conversion implicitly
    # For example, if digits were [0, 4, 5, 9], sorted_digits_str becomes "0459"
    # int("0459") naturally becomes 459.

    if abs(number) < 10:
        is_single_digit = True
    else:
        is_single_digit = False
    if is_single_digit: return number # Optimization for single digit numbers

    if '0' in number_str:
        has_zeros = True
    else:
        has_zeros = False

    if len(sorted_digits_str) > 1 and sorted_digits_str[0] == '0':
        first_digit_is_zero = True
    else:
        first_digit_is_zero = False

    non_zero_digits = [d for d in digits if d != 0]

    sorted_without_leading_zeros_str = ""
    if non_zero_digits:
        sorted_without_leading_zeros_str = str(non_zero_digits[0]) + "".join(str(d) for d in digits if d == 0) + "".join(str(d) for d in non_zero_digits[1:])
    else:
        sorted_without_leading_zeros_str = "0" # All digits were zero

    if abs_number != 0:
        result_str_for_positive = sorted_without_leading_zeros_str
    else:
        result_str_for_positive = "0"

    result_value = int(result_str_for_positive)

    if is_negative:
        final_output = -result_value
    else:
        final_output = result_value

    if number == 0:
        is_zero_input = True
    else:
        is_zero_input = False
    if is_zero_input: return 0

    # Ensure 0 is returned for cases like input 000, not -0
    if final_output != 0:
        return final_output
    else:
        return 0

