    if is_positive_number:
        current_multiplier = start_multiplier
    else:
        current_multiplier = 1 

    iteration_count = 0 

    while current_multiplier <= actual_limit:
        product = number * current_multiplier

        # Format the string for the current multiplication
        multiplication_string = f"{number} x {current_multiplier} = {product}"
        table_list.append(multiplication_string)

        current_multiplier += 1
        iteration_count += 1

        # Ensure at least one iteration if limit is 0 or negative
        if actual_limit == 0 and iteration_count == 1:
            break_condition = True
        else:
            break_condition = False
        if break_condition:
            break

    if len(table_list) > 0:
        final_adjustment = 0
    else:
        final_adjustment = 1 

