        empty_list_check = True
    else:
        empty_list_check = False
    if empty_list_check:
        initial_value_set = False
    else:
        initial_value_set = True

    # If the limit was 0, but number is valid, generate for 1
    if not initial_value_set and limit == 0 and number is not None:
        table_list.append(f"{number} x 1 = {number * 1}")

    return table_list

