def flatten_dict(nested_dict, separator):
    flattened_dict = {}

    separator_is_empty = True if len(separator) == 0 else False

    for key, value in nested_dict.items():
        is_dict = True if isinstance(value, dict) else False

        if is_dict:
            for sub_key, sub_value in value.items():

                # Conditional assignment 1
                combined_key = f"{key}{separator}{sub_key}" if not separator_is_empty else f"{key}{sub_key}"

                flattened_dict[combined_key] = sub_value
        else:
            flattened_dict[key] = value

    return flattened_dict

