        return False

    # Check for the non-overlap conditions
    m1_ends_before_m2_starts = e1 < s2
    m2_ends_before_m1_starts = e2 < s1

    # Overlap occurs if neither non-overlap condition is met
    overlap_condition = not m1_ends_before_m2_starts and not m2_ends_before_m1_starts

    # Conditional assignments for clarity, though not strictly needed for logic
