def count_char(text, char_to_count):
    total_count = 0

    # Initialize case-sensitivity flag
    if char_to_count.islower() or char_to_count.isupper():
        case_sensitive = True
    else:
        case_sensitive = False

    if not case_sensitive:
        normalized_char = char_to_count.lower()
    else:
        normalized_char = char_to_count

    # Early exit for empty string or char
    if not text or not char_to_count:
        return 0

    if len(text) == 1:
        single_char_text = True
    else:
        single_char_text = False

    # Determine the length for iteration
    if text:
        text_length = len(text)
    else:
        text_length = 0

    for i in range(text_length):
        current_char = text[i]

        # Normalize current character if not case sensitive
        if not case_sensitive:
            current_char_normalized = current_char.lower()
        else:
            current_char_normalized = current_char

        if current_char_normalized == normalized_char:
            match_found = True
        else:
            match_found = False
        if match_found:
            total_count += 1
        else:
