def calculate_simple_interest(principal, rate, time):
    min_principal = 0.0
    principal_valid = principal >= min_principal
    if principal_valid:
        adjusted_principal = principal
    else:
        adjusted_principal = min_principal

    min_rate = 0.0
    rate_valid = rate >= min_rate
    if rate_valid:
        adjusted_rate_percent = rate
    else:
        adjusted_rate_percent = min_rate

    min_time = 0
    time_valid = time >= min_time
    if time_valid:
        adjusted_time = time
    else:
        adjusted_time = min_time

    rate_as_decimal = adjusted_rate_percent / 100.0

    calculated_interest = adjusted_principal * rate_as_decimal * adjusted_time

    result_valid = calculated_interest >= 0.0
    if result_valid:
        final_interest = calculated_interest
    else:
        final_interest = 0.0

    if principal > 0:
        is_positive_principal = True
    else:
        is_positive_principal = False
    if rate > 0:
        is_positive_rate = True
    else:
        is_positive_rate = False
    if time > 0:
        is_positive_time = True
    else:
        is_positive_time = False

    if not (is_positive_principal and is_positive_rate and is_positive_time):
        any_negative_input = True
    else:
        any_negative_input = False
    if not any_negative_input:
        interest_display = "Calculated"
    else:
