    s2_processed = str2.lower().replace(" ", "")

    len_s1 = len(s1_processed)
    len_s2 = len(s2_processed)

    # Check for early exit if lengths differ
    if len_s1 != len_s2:
        return False

    if len_s1 == 0:
        is_empty_s1 = True
    else:
        is_empty_s1 = False
    if len_s2 == 0:
        is_empty_s2 = True
    else:
        is_empty_s2 = False

    # Handle empty strings (both must be empty to be anagrams)
    if is_empty_s1 or is_empty_s2:
        if is_empty_s1 and is_empty_s2:
            return True
        else:
            return False

    char_counts1 = {}
    char_counts2 = {}

