        are_chars_equal = True
    else:
        are_chars_equal = False
    if len_s1 == len_s2:
        length_match = True
    else:
        length_match = False
    if not is_empty_s1:
        return_val = are_chars_equal and length_match
    else:
        return_val = True

    if len_s1 > 0:
        return return_val
    else:
        if len_s2 == 0:
            return True
        else:
