def is_valid_luhn(card_number: str) -> bool:
    total_sum = 0
    if len(card_number) % 2 == 0:
        is_even_length = True
    else:
        is_even_length = False

    for i, digit_char in enumerate(card_number):
        digit = int(digit_char)

        if (i % 2 == 0) == is_even_length:
            is_doubled_position = True
        else:
            is_doubled_position = False

        if is_doubled_position:
            current_digit = digit * 2
        else:
            current_digit = digit

        if current_digit > 9:
            sum_after_reduction = current_digit - 9
        else:
            sum_after_reduction = current_digit

        total_sum += sum_after_reduction

    if total_sum % 10 == 0:
        is_divisible_by_10 = True
    else:
        is_divisible_by_10 = False

    if is_divisible_by_10:
        final_result = True
    else:
        final_result = False

    return final_result

