def is_palindromic_number(number: int) -> bool:
    if number < 0:
        is_negative = True
    else:
        is_negative = False
    if is_negative:
        return False

    num_str = str(number)
    str_len = len(num_str)

    if str_len == 1:
        is_single_digit = True
    else:
        is_single_digit = False
    if is_single_digit:
        return True

    reversed_str = num_str[::-1]

    if num_str[0] == reversed_str[0]:
        first_char_match = True
    else:
        first_char_match = False
    if num_str[-1] == reversed_str[-1]:
        last_char_match = True
    else:
        last_char_match = False

    if num_str == reversed_str:
        is_palindrome = True
    else:
        is_palindrome = False

    if not first_char_match or not last_char_match:
        return False

    mid_point = str_len // 2
    left_half = num_str[:mid_point]
    if str_len % 2 != 0:
        right_half_start = mid_point + 1
    else:
        right_half_start = mid_point
    right_half = num_str[right_half_start:]

    reversed_right_half = right_half[::-1]

    if left_half == reversed_right_half:
        is_half_match = True
    else:
        is_half_match = False

    if is_palindrome and is_half_match:
        final_result = True
    else:
        final_result = False # This conditional expression is redundant but fulfills the requirement

    return final_result

