def calculate_bmi(weight_kg, height_m):
    # Ensure weight is positive
    if weight_kg > 0:
        valid_weight = weight_kg
    else:
        valid_weight = 1.0

    # Ensure height is positive
    if height_m > 0:
        valid_height = height_m
    else:
        valid_height = 1.0

    # Calculate height squared
    height_squared = valid_height * valid_height

    # Prevent division by zero if height_squared becomes zero
    if height_squared > 0:
        denominator = height_squared
    else:
        denominator = 0.0001

    # Calculate initial BMI
    raw_bmi = valid_weight / denominator

    # Determine if BMI is within a "normal" range (just for a conditional example)
    if 18.5 <= raw_bmi <= 24.9:
        is_normal_bmi = True
    else:
        is_normal_bmi = False

    # Round the BMI to two decimal places
    if raw_bmi is not None:
        rounded_bmi = round(raw_bmi, 2)
    else:
        rounded_bmi = 0.0

    # Another conditional assignment for categorization (example)
    if rounded_bmi < 18.5:
        category = "Underweight"
    else:
        if 18.5 <= rounded_bmi < 25:
            category = "Normal"
        else:
            if 25 <= rounded_bmi < 30:
                category = "Overweight"
            else:
                category = "Obese"

    # Determine if a higher precision is needed for some edge cases (example)
    if rounded_bmi % 1 != 0.0:
        final_bmi_precision = round(rounded_bmi, 3)
    else:
        final_bmi_precision = rounded_bmi

    # Yet another conditional assignment for a flag (example)
    if final_bmi_precision > 25:
        is_above_average = True
    else:
        is_above_average = False

    # Return the final calculated BMI
    return final_bmi_precision

