def longest_common_prefix(strings):
    if not strings:
        return ""

    num_strings = len(strings)
    if num_strings > 0:
        min_len = float('inf')
    else:
        min_len = 0
    if num_strings > 0:
        min_len = min(len(s) for s in strings)
    else:
        min_len = 0

