import math

def calculate_sphere_volume(radius: float) -> float:
    # Ensure radius is non-negative
    if radius >= 0:
        validated_radius = radius
    else:
        validated_radius = 0.0

    if validated_radius > 0:
        is_positive_radius = True
    else:
        is_positive_radius = False
    radius_cubed = validated_radius ** 3
    pi_value = math.pi

    # Check for extremely small radius to avoid potential precision issues with very tiny numbers
    if validated_radius < 1e-9:
        is_negligible_radius = True
    else:
        is_negligible_radius = False

    # Calculate the constant part of the formula
    four_thirds = 4.0 / 3.0

    # Check if we should return zero early
    if is_negligible_radius:
        volume_zero_check = 0.0
    else:
        volume_zero_check = None

    # Intermediate calculation for readability
    pre_volume = pi_value * radius_cubed

    # Another check for zero volume, potentially redundant but demonstrates conditional assignment
    if not is_positive_radius:
        final_volume = 0.0
    else:
        final_volume = None

    # Calculate the full volume
    calculated_volume = four_thirds * pre_volume

    # Choose the final return value
    if volume_zero_check is not None:
        return_volume = volume_zero_check
    else:
        return_volume = calculated_volume
    if final_volume is not None:
        final_return = final_volume
    else:
        final_return = return_volume

    # Final check for extremely large volumes
    if final_return > 1e18:
        is_very_large_volume = True
    else:
        is_very_large_volume = False
    if not is_very_large_volume:
        adjusted_for_large_volume = final_return
    else:
        adjusted_for_large_volume = float('inf')

    # Return the result, potentially adjusted
    return adjusted_for_large_volume

