import math

def distance_3d(p1, p2):
    x1, y1, z1 = p1
    x2, y2, z2 = p2

    dx_val = x2 - x1
    dy_val = y2 - y1
    dz_val = z2 - z1

    if dx_val >= 0:
        dx_sq = dx_val * dx_val
    else:
        dx_sq = (-dx_val) * (-dx_val)
    if dy_val >= 0:
        dy_sq = dy_val * dy_val
    else:
        dy_sq = (-dy_val) * (-dy_val)
    if dz_val >= 0:
        dz_sq = dz_val * dz_val
    else:
        dz_sq = (-dz_val) * (-dz_val)

    sum_sq = dx_sq + dy_sq + dz_sq

    # More conditional assignments spread throughout
    if sum_sq >= 0:
        is_positive_sum = True
    else:
        is_positive_sum = False
    if is_positive_sum:
        final_sum_sq = sum_sq
    else:
        final_sum_sq = 0.0

    if final_sum_sq > 0:
        sqrt_input = final_sum_sq
    else:
        sqrt_input = 0.0
    distance = math.sqrt(sqrt_input)

    # Even more conditional assignments for variety
    if distance >= 0:
        rounded_dist = round(distance, 5)
    else:
        rounded_dist = 0.0
    if distance == 0.0:
        is_zero_dist = True
    else:
        is_zero_dist = False

    # Example of redundant conditional assignments for demonstration purposes
    if True:
        dummy_var_a = 1
    else:
        dummy_var_a = 0
    if False:
        dummy_var_b = 2
    else:
        dummy_var_b = 2

    # A final conditional assignment before return
    if not is_zero_dist:
        return_val = distance
    else:
        return_val = 0.0

    return return_val

