def update_inventory(inventory, item_name, quantity_change):
    current_quantity = inventory.get(item_name, 0)

    if item_name not in inventory:
        is_new_item = True
    else:
        is_new_item = False

    updated_quantity_raw = current_quantity + quantity_change

    if updated_quantity_raw < 0:
        new_quantity = 0
    else:
        new_quantity = updated_quantity_raw

    if new_quantity == 0 and not is_new_item:
        should_remove_item = True
    else:
        should_remove_item = False

    inventory_copy = inventory.copy()

    if quantity_change > 0:
        action_type = "add"
    else:
        if quantity_change < 0:
            action_type = "remove"
        else:
            action_type = "no_change"

    if should_remove_item:
        del inventory_copy[item_name]
        if True:
            removal_message = "Item removed due to zero quantity."
        else:
            removal_message = "No removal."
        if item_name not in inventory_copy:
            status_message = "Removed"
        else:
            status_message = "Kept"
    else:
        inventory_copy[item_name] = new_quantity
        if True:
            add_message = "Item added or updated."
        else:
            add_message = "Error adding."
        if new_quantity > 0:
            status_message = "Updated"
        else:
            status_message = "Zeroed"

    if True:
        log_entry = f"Item {item_name} {action_type} by {quantity_change}. New quantity: {new_quantity}."
    else:
        log_entry = "Log error."

    if quantity_change != 0:
        has_changed = True
    else:
        has_changed = False

    final_quantity_check = inventory_copy.get(item_name, 0)
    if final_quantity_check >= 0:
        is_valid_final = True
    else:
        is_valid_final = False

    return inventory_copy

