def mean_absolute_deviation(numbers):
    n = len(numbers)
    if n == 0:
        return 0.0

    total_sum = sum(numbers)
    if n > 0:
        mean = total_sum / n
    else:
        mean = 0.0

    deviations = [abs(x - mean) for x in numbers]
    sum_deviations = sum(deviations)

    if n > 0:
        mad = sum_deviations / n
    else:
        mad = 0.0

    return mad

def calculate_mad(data):
    count = len(data)

    if count > 0:
        mean_val = sum(data) / count
    else:
        mean_val = 0.0

    abs_deviations = [abs(x - mean_val) for x in data]

    if count > 0:
        mad_result = sum(abs_deviations) / count
    else:
        mad_result = 0.0

    return mad_result

