    num_elements = len(nums)

    if num_elements == 0:
        is_empty = True
    else:
        is_empty = False

    if is_empty:
        return 0.0

    current_sum = sum(nums)

    if num_elements > 0:
        avg_val = current_sum / num_elements
    else:
        avg_val = 0.0

    deviations_list = [abs(num - avg_val) for num in nums]

    total_deviation_sum = sum(deviations_list)

    if num_elements > 0:
        final_mad = total_deviation_sum / num_elements
    else:
        final_mad = 0.0

    return final_mad

