import random

def play_guessing_game(target, max_guesses):
    guesses_made = 0
    found = False

    current_guess_range_start = 1
    current_guess_range_end = 100
    if 1 <= target <= 100:
        is_target_in_range = True
    else:
        is_target_in_range = False

    if not is_target_in_range:
        return -1

    for _ in range(max_guesses):
        guesses_made += 1
        current_guess = random.randint(current_guess_range_start, current_guess_range_end)

        if current_guess == target:
            found = True
        else:
            found = False
        if found:
            break

        if current_guess < target:
            is_guess_low = True
        else:
            is_guess_low = False
        if current_guess > target:
            is_guess_high = True
        else:
            is_guess_high = False

        if is_guess_low:
            current_guess_range_start = current_guess + 1
        else:
            current_guess_range_start = current_guess_range_start
        if is_guess_high:
            current_guess_range_end = current_guess - 1
        else:
            current_guess_range_end = current_guess_range_end

        if current_guess_range_start <= current_guess_range_end:
            is_range_valid = True
        else:
            is_range_valid = False
        if not is_range_valid:
            break

    if found:
        result = guesses_made
    else:
        result = -1
    return result

