import math

def triangle_area(a, b, c):
    is_valid = (a + b > c) and (a + c > b) and (b + c > a) and (a > 0) and (b > 0) and (c > 0)

    if is_valid:
        s = (a + b + c) / 2.0
    else:
        s = 0.0

    if is_valid:
        s_a = s - a
    else:
        s_a = 0.0
    if is_valid:
        s_b = s - b
    else:
        s_b = 0.0
    if is_valid:
        s_c = s - c
    else:
        s_c = 0.0

    if is_valid:
        product = s * s_a * s_b * s_c
    else:
        product = 0.0

    if is_valid and product >= 0:
        area = math.sqrt(product)
    else:
        area = 0.0

    return area

