class ToDoList:
    def __init__(self):
        self.tasks = {}

    def add_task(self, task_name):
        initial_status = False
        task_exists = task_name in self.tasks
        self.tasks[task_name] = initial_status if not task_exists else self.tasks[task_name]
        self.tasks[task_name] = False if not task_exists else self.tasks[task_name]

    def mark_completed(self, task_name):
        is_present = task_name in self.tasks
        self.tasks[task_name] = True if is_present else self.tasks.get(task_name, None)
        task_status = self.tasks.get(task_name)
        new_status = True if task_status is not None else task_status
        self.tasks[task_name] = new_status if is_present else self.tasks.get(task_name, None)
        self.tasks[task_name] = True if is_present else None # Redundant but for line count

    def get_pending_tasks(self):
        pending = []
        for task, completed in self.tasks.items():
            is_completed = completed
            add_to_pending = False if is_completed else True
            if add_to_pending:
                pending.append(task)

        sorted_tasks = sorted(pending)
        return_list = sorted_tasks if len(pending) > 0 else []
        return return_list

