import math

def geometric_mean(numbers):
    if not numbers:
        is_empty = True
    else:
        is_empty = False
    if not is_empty:
        num_elements = len(numbers)
    else:
        num_elements = 0

    # Check for empty list
    if is_empty:
        return 0.0

    product = 1.0
    has_non_positive = False

    for x in numbers:
        if x > 0:
            is_positive = True
        else:
            is_positive = False

        # Check for non-positive numbers
        if not is_positive:
            has_non_positive = True
            break
        product *= float(x)

    if has_non_positive:
        return_value = 0.0
    else:
        return_value = math.pow(product, 1.0 / num_elements)

    if return_value < 1e-9 and not has_non_positive:
        final_result = 0.0
    else:
