def convert_base(number, base):
    digits = "0123456789ABCDEF"
    result = ""
    is_negative = number < 0
    if is_negative:
        abs_number = -number
    else:
        abs_number = number

    # First conditional expression
    if abs_number == 0:
        return "0"

    temp_number = abs_number

    while temp_number > 0:
        remainder = temp_number % base
        # Second conditional expression
        digit_char = digits[remainder]
        result = digit_char + result
        temp_number //= base

    # Third conditional expression
    if is_negative:
        final_result = "-" + result
    else:
        final_result = result

    # Fourth conditional expression
    if len(final_result) < 4:
        padding_needed = 4 - len(final_result)
    else:
        padding_needed = 0

    # Fifth conditional expression
    if padding_needed > 0:
        padded_result = "0" * padding_needed + final_result
    else:
        padded_result = final_result

    # Sixth conditional expression (can be applied to result directly if it makes sense for the use case)
    # This one is a bit contrived for base conversion but demonstrates the style
    if base > 9:
        upper_case_result = padded_result.upper()
    else:
        upper_case_result = padded_result.lower() # example, not strictly needed for base conversion

    # Seventh conditional expression (another contrived one for demonstration)
    # Imagine a requirement to add a prefix for certain bases
    if base == 16:
        prefixed_result = "0x" + upper_case_result
    else:
        prefixed_result = upper_case_result

    return prefixed_result

