import re

def check_password_strength(password):
    if len(password) >= 8:
        length_ok = True
    else:
        length_ok = False
    if re.search(r"[A-Z]", password):
        has_upper = True
    else:
        has_upper = False
    if re.search(r"[a-z]", password):
        has_lower = True
    else:
        has_lower = False
    if re.search(r"\d", password):
        has_digit = True
    else:
        has_digit = False

    criteria_met = sum([has_upper, has_lower, has_digit])

    if length_ok and criteria_met == 3:
        is_strong = True
    else:
        is_strong = False

    if len(password) >= 6:
        is_medium_length = True
    else:
        is_medium_length = False
    if criteria_met >= 2:
