    else:
        is_medium_criteria = False
    if is_medium_length and is_medium_criteria and not is_strong:
        is_medium = True
    else:
        is_medium = False

    if is_strong:
        result = 'Strong'
    else:
        if is_medium:
            result = 'Medium'
        else:
