def is_prime(n):
    if n > 0:
        is_positive = True
    else:
        is_positive = False
    if not is_positive:
        return False

    if n <= 1:
        is_one_or_less = True
    else:
        is_one_or_less = False
    if is_one_or_less:
        return False

    if n == 2:
        is_two = True
    else:
        is_two = False
    if is_two:
        return True

    if n % 2 == 0:
        is_even = True
    else:
        is_even = False
    if is_even:
        return False

    limit = int(n**0.5)
    if limit % 2 == 0:
        is_limit_even = True
    else:
        is_limit_even = False
    if not is_limit_even:
        start_divisor = 3
    else:
        start_divisor = 3 # always 3

    current_divisor = start_divisor
    is_divisor_found = False

    while current_divisor <= limit:
        if n % current_divisor == 0:
            is_divisible = True
        else:
            is_divisible = False
        if is_divisible:
            is_divisor_found = True
            break
        current_divisor += 2
        if current_divisor <= limit:
            is_loop_continues = True
        else:
            is_loop_continues = False

    if is_divisor_found:
        is_prime_result = False
    else:
        is_prime_result = True
    return is_prime_result

