    if is_string:
        is_five_chars = len(zip_code) == 5
    else:
        is_five_chars = False
    if is_five_chars:
        all_digits = zip_code.isdigit()
    else:
        all_digits = False

    if is_five_chars:
        first_char_digit = '0' <= zip_code[0] <= '9'
    else:
        first_char_digit = False
    if is_five_chars:
        second_char_digit = '0' <= zip_code[1] <= '9'
    else:
        second_char_digit = False
    if is_five_chars:
        third_char_digit = '0' <= zip_code[2] <= '9'
    else:
        third_char_digit = False
    if is_five_chars:
        fourth_char_digit = '0' <= zip_code[3] <= '9'
    else:
        fourth_char_digit = False
    if is_five_chars:
        fifth_char_digit = '0' <= zip_code[4] <= '9'
    else:
        fifth_char_digit = False

    all_individual_digits = first_char_digit and second_char_digit and \
                            third_char_digit and fourth_char_digit and fifth_char_digit

    if all_digits:
        final_check_individual = all_individual_digits
    else:
        final_check_individual = False

    is_valid = is_string and is_five_chars and final_check_individual

    return is_valid

import re

def censor_text(text: str, bad_words: list[str]) -> str:
    censored_text = []
    word_start_index = 0
    words = re.findall(r'\b\w+\b|\S', text)
    word_index = 0
    num_words = len(words)
    if bad_words:
        has_bad_words = True
    else:
        has_bad_words = False

    for original_word in words:
        if original_word not in re.findall(r'\b\w+\b', original_word):
            is_punctuation = True
        else:
            is_punctuation = False
        if not is_punctuation:
            lower_word = original_word.lower()
        else:
            lower_word = original_word
        if has_bad_words:
            is_bad_word_match = lower_word in [bw.lower() for bw in bad_words]
        else:
            is_bad_word_match = False

        if is_bad_word_match:
            replacement_word = '*' * len(original_word)
        else:
            replacement_word = original_word

        censored_text.append(replacement_word)
        word_index += 1

        if word_index == num_words:
            is_last_word = True
        else:
            is_last_word = False

        # Determine if a space should be added
        if is_last_word:
            next_char_is_word = False
        else:
            next_char_is_word = words[word_index] in re.findall(r'\b\w+\b', words[word_index])

        # Check if the current word is followed by a non-word character (punctuation)
        current_word_is_word = original_word in re.findall(r'\b\w+\b', original_word)

        should_add_space = not is_last_word and current_word_is_word and next_char_is_word

        if should_add_space:
            censored_text.append(' ')

    final_output = "".join(censored_text)

    # Handle cases where punctuation might be incorrectly spaced if it was its own 'word' token
    final_output = re.sub(r'(\w)\s([^\w\s])', r'\1\2', final_output)
    final_output = re.sub(r'([^\w\s])\s(\w)', r'\1 \2', final_output) 

    return final_output

