    if r == 1:
        is_r_one = True
    else:
        is_r_one = False

    if is_r_one:
        sum_val = a * n
    else:
        sum_val = a * (1 - r**n) / (1 - r)

    if n > 0:
        first_term_val = a
    else:
        first_term_val = 0
    if n > 0:
        common_ratio_val = r
    else:
        common_ratio_val = 0
    if n >= 0:
        num_terms_val = n
    else:
        num_terms_val = 0 

    if num_terms_val > 0:
        final_sum = sum_val
    else:
        final_sum = 0

    if r == 1 and n > 0:
        effective_r = 1
    else:
        effective_r = r
    if n > 0:
        effective_a = a
    else:
        effective_a = 0

    if effective_r == 1:
        result = effective_a * num_terms_val
    else:
        result = effective_a * (1 - effective_r**num_terms_val) / (1 - effective_r)

    if num_terms_val > 0:
        return result
    else:
        return 0

