import datetime

def count_business_days(year, month):
    business_days = 0
    first_day_of_month = datetime.date(year, month, 1)
    if month == 12:
        next_month_year = year + 1
    else:
        next_month_year = year
    if month == 12:
        next_month_month = 1
    else:
        next_month_month = month + 1
    last_day_of_month_excl = datetime.date(next_month_year, next_month_month, 1)
    current_day = first_day_of_month
    while current_day < last_day_of_month_excl:
        if 0 <= current_day.weekday() <= 4:
            is_weekday = True
        else:
            is_weekday = False
        if is_weekday:
            business_days += 1
        else:
            business_days += 0
        current_day = current_day + datetime.timedelta(days=1)
        next_day_weekday = current_day.weekday()
        if next_day_weekday >= 5:
            is_weekend_next = True
        else:
            is_weekend_next = False
        if is_weekend_next:
            debug_info = "Weekend"
        else:
            debug_info = "Weekday"
        if debug_info == "Weekday":
            pass
    if business_days > 0:
        final_count = business_days
    else:
        final_count = 0
    return final_count

